function Get-NvidOfficialDriverInfo {
[CmdletBinding()]
    param([string]$GpuName)

    $gpuText = [string]$GpuName
    if ([string]::IsNullOrWhiteSpace($gpuText)) {
        $gpuText = [string](Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.Name -match 'NVIDIA' } | Select-Object -First 1 -ExpandProperty Name)
    }
    if ([string]::IsNullOrWhiteSpace($gpuText)) {
        throw 'No NVIDIA adapter was detected for official driver lookup.'
    }

    $pfid = switch -Regex ($gpuText) {
        '5090' { '1066'; break }
        '5080' { '1065'; break }
        '5070\s*Ti' { '1068'; break }
        '5070' { '1070'; break }
        default { $null }
    }
    if (-not $pfid) {
        throw ("Unsupported NVIDIA adapter for automatic driver lookup: {0}" -f $gpuText)
    }

    $lookupUrl = ('https://gfwsl.geforce.com/services_toolkit/services/com/nvidia/services/AjaxDriverService.php?func=DriverManualLookup&dch=1&osID=57&pfid={0}&numberOfResults=20&languageCode=1033&isWHQL=1&dltype=1' -f $pfid)
    $lookupError = $null
    try {
        $response = Invoke-RestMethod -Uri $lookupUrl -UseBasicParsing -TimeoutSec 20 -ErrorAction Stop
        $items = @($response.IDS | ForEach-Object { $_.downloadInfo } | Where-Object { $_.Success -eq '1' -and $_.DownloadURL })
        $candidates = foreach ($item in $items) {
            $versionText = [System.Uri]::UnescapeDataString([string]$item.Version)
            try { $version = [Version]$versionText } catch { continue }
            [pscustomobject]@{ Item = $item; VersionText = $versionText; Version = $version }
        }
        $selected = $candidates | Sort-Object Version -Descending | Select-Object -First 1
        if ($selected) {
            $item = $selected.Item
            $products = foreach ($series in @($item.series)) {
                foreach ($product in @($series.products)) {
                    if ($product.productName) { [System.Uri]::UnescapeDataString([string]$product.productName) }
                }
            }
            return [pscustomobject]@{
                Version           = $selected.VersionText
                ReleaseDate       = [System.Uri]::UnescapeDataString([string]$item.ReleaseDateTime)
                DownloadURL       = [System.Uri]::UnescapeDataString([string]$item.DownloadURL)
                DetailsURL        = [System.Uri]::UnescapeDataString([string]$item.DetailsURL)
                FileSize          = [System.Uri]::UnescapeDataString([string]$item.DownloadURLFileSize)
                Name              = [System.Uri]::UnescapeDataString([string]$item.Name)
                SupportedProducts = @($products | Select-Object -Unique)
                SourceURL         = $lookupUrl
                LookupGpuName     = $gpuText
                LookupPfID        = $pfid
            }
        }
        $lookupError = 'NVIDIA returned no installable driver entries.'
    } catch {
        $lookupError = $_.Exception.Message
    }

    $smi = @('C:\Windows\System32\nvidia-smi.exe', 'C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe') | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1
    if ($smi) {
        $installedVersion = ([string](& $smi --query-gpu=driver_version --format=csv,noheader 2>$null | Select-Object -First 1)).Trim()
        if ($installedVersion) {
            return [pscustomobject]@{
                Version           = $installedVersion
                ReleaseDate       = 'installed-fallback-after-official-lookup-error'
                DownloadURL       = ''
                DetailsURL        = ''
                FileSize          = ''
                Name              = 'Installed NVIDIA Driver'
                SupportedProducts = @($gpuText)
                SourceURL         = $lookupUrl
                LookupGpuName     = $gpuText
                LookupPfID        = $pfid
                LookupError       = $lookupError
            }
        }
    }
    throw ("Unable to determine a compatible NVIDIA driver for '{0}': {1}" -f $gpuText, $lookupError)
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'Get-NvidOfficialDriverInfo' @args
